// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Ownership should always belong to the deployer initially;
        // transferring to a non-zero owner should update it accordingly.
        vm.assume(newOwner != address(0));
        // deployer is address(this) → owner() must equal address(this)
        assertTrue(c.owner() == address(this));
        // after a valid transfer, owner() must reflect the new owner
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}

