pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(address fuzzedOwner) public {
        vm.assume(fuzzedOwner != address(0));
        // Transfer ownership to a fuzzed address
        vm.prank(address(this));
        c.transferOwnership(fuzzedOwner);

        // The buggy M will revert when owner() is called because it doesn't return a value
        bool ok;
        address returnedOwner;
        try c.owner() returns (address owner_) {
            ok = true;
            returnedOwner = owner_;
        } catch {
            ok = false;
        }

        // For the reference C, ok is always true and returnedOwner equals fuzzedOwner.
        // For the buggy M, ok is false (revert) for at least some input.
        assertTrue(ok && returnedOwner == fuzzedOwner);
    }
}

