pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // The fuzzer supplies any address, including address(0)
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        if (newOwner == address(0)) {
            // The reference contract must revert when transferring to zero address.
            // The mutant accepts it, so ok will be true.
            assertFalse(ok);
        } else {
            // For non-zero addresses, both should succeed.
            assertTrue(ok);
        }
    }
}

