pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this) && newOwner != c.owner());
        address originalOwner = c.owner();
        vm.prank(originalOwner);
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        if (success) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Allow any address as the new owner candidate, including address(0)
        // The owner is initially address(this); only the owner can call transferOwnership
        vm.prank(address(this));
        bool didNotRevert;
        try c.transferOwnership(newOwner) {
            didNotRevert = true;
        } catch {
            didNotRevert = false;
        }
        // If the call did not revert, owner() must be non-zero.
        // The reference implementation reverts on address(0), so didNotRevert is false there, and the assertion vacuously holds.
        // The buggy version allows address(0) and then owner() becomes address(0), violating the assertion.
        assertTrue(!didNotRevert || c.owner() != address(0));
    }
}
